def L(lang):
    ids = ["home", "paragvay-hub", "turizm", "uslugi", "zhizn-v-paragvae", "pochemu-paragvay"] + \
          [f"attr-{a['id']}" for a in ATTRACTIONS]
    return {pid: href_to(pid, lang) for pid in ids}


def gimages_url(query):
    return f"https://www.google.com/search?tbm=isch&q={quote(query)}"


def photo_block(lang, query):
    url = gimages_url(query)
    link = f'<a href="{url}" target="_blank" rel="noopener noreferrer">{PHOTO_LINK_TEXT[lang]}</a>'
    text = PHOTO_TEXT[lang].format(q=query, link=link)
    return f'<div class="callout"><span class="callout-label">{PHOTO_LABEL[lang]}</span>{text}</div>'


def crumbs_hub(lang):
    l = L(lang)
    return breadcrumbs([
        (NAV_LABELS[lang]["home"], l["home"]),
        (NAV_LABELS[lang]["paragvay-hub"], l["paragvay-hub"]),
        (TURIZM_LABEL[lang], None),
    ])


def crumbs_attr(lang, title):
    l = L(lang)
    return breadcrumbs([
        (NAV_LABELS[lang]["home"], l["home"]),
        (NAV_LABELS[lang]["paragvay-hub"], l["paragvay-hub"]),
        (TURIZM_LABEL[lang], l["turizm"]),
        (title, None),
    ])


def schema_crumbs_hub(lang):
    l = L(lang)
    return schema_breadcrumb([
        (NAV_LABELS[lang]["home"], f"/{lang}/"),
        (NAV_LABELS[lang]["paragvay-hub"], f"/{lang}/{l['paragvay-hub']}"),
        (TURIZM_LABEL[lang], f"/{lang}/{l['turizm']}"),
    ])


def schema_crumbs_attr(lang, page_id, title):
    l = L(lang)
    return schema_breadcrumb([
        (NAV_LABELS[lang]["home"], f"/{lang}/"),
        (NAV_LABELS[lang]["paragvay-hub"], f"/{lang}/{l['paragvay-hub']}"),
        (TURIZM_LABEL[lang], f"/{lang}/{l['turizm']}"),
        (title, f"/{lang}/{l[page_id]}"),
    ])


# =============================================================== СБОРКА

def build_turizm_hub():
    for lang in LANGS:
        l = L(lang)
        cards_by_region = {r: "" for r in REGION_ORDER}
        for a in ATTRACTIONS:
            tr = ATTR_TEXT[a["id"]][lang]
            cards_by_region[a["region"]] += f'''
    <article class="card" style="margin-bottom:24px;">
      <h3>{tr["title"]}</h3>
      <p style="font-size:16px;">{tr["teaser"]}</p>
      <a class="card-link" href="{l['attr-' + a["id"]]}">{MORE_LABEL[lang]}</a>
    </article>'''

        regions_html = ""
        for r in REGION_ORDER:
            regions_html += f'''
    <h2>{REGION_LABEL[r][lang]}</h2>
    {cards_by_region[r]}'''

        m = HUB_META[lang]
        body = f'''
{crumbs_hub(lang)}
<section class="hero" style="padding-top:24px;">
  <div class="wrap"><h1>{m["h1"]}</h1>
  <p class="lead">{m["lead"]}</p>
  </div>
</section>
<section style="padding-top:0;">
  <div class="prose">
    {regions_html}
  </div>
</section>
'''
        page("turizm", lang, m["title"], m["description"], body, extra_schema=schema_crumbs_hub(lang))


def build_attraction_pages():
    for lang in LANGS:
        l = L(lang)
        for a in ATTRACTIONS:
            tr = ATTR_TEXT[a["id"]][lang]
            page_id = "attr-" + a["id"]
            body_text = tr["body"].format(zhizn=l["zhizn-v-paragvae"])
            body = f'''
{crumbs_attr(lang, tr["title"])}
<section class="hero" style="padding-top:24px;">
  <div class="wrap"><h1>{tr["title"]}</h1>
  <p class="lead">{tr["teaser"]}</p>
  </div>
</section>
<section style="padding-top:0;">
  <div class="prose">
    {photo_block(lang, a["img_query"])}
    {body_text}
    <p><a href="{l['turizm']}">{BACK_LINK[lang]}</a></p>
  </div>
</section>
'''
            page(page_id, lang, f'{tr["title"]} | {ATTR_META_SUFFIX[lang]} | Grund Paraguay', tr["teaser"],
                 body, extra_schema=schema_crumbs_attr(lang, page_id, tr["title"]))


build_turizm_hub()
build_attraction_pages()
